-- 2025年案款账套科目期初及辅助核算期初导入
-- 来源文件：期初.xlsx；SHA-256：97053471b525cf9f267e7a8ce3e0810b4c2df87bea88e784a08bb2e4e1ca69f8
-- 目标账套：CASE_FUND_2025（00000000-0000-0000-0000-000000000101）
-- 目标期间：2025-01
-- 财务口径：100201借方34,247,184.19；200301贷方33,415,388.11；200302贷方831,796.08；借贷平衡。
-- 200301共630条案号+收据号辅助明细，组合不重复且均非空。
-- 源表第63行贷方为-478.05，本补丁按源值保留，以保证科目总额与辅助明细精确一致。
-- 安全策略：先执行账套、期间、科目、辅助配置、源数据合计及现有数据冲突检查；任一失败即中止并回滚。
-- 重复执行：活动数据结果幂等；已有非零且与本批次不一致的数据会触发保护，不会被覆盖。

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @account_set_id = '00000000-0000-0000-0000-000000000101';
SET @period = '2025-01';
SET @operator_id = 'system';
SET @patch_tag = '2026-07-25-import-2025-case-fund-opening';
SET @source_sha256 = '97053471b525cf9f267e7a8ce3e0810b4c2df87bea88e784a08bb2e4e1ca69f8';

DROP TEMPORARY TABLE IF EXISTS tmp_20250725_opening_subject;
CREATE TEMPORARY TABLE tmp_20250725_opening_subject (
    subject_code varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL PRIMARY KEY,
    debit_amount decimal(18,2) NOT NULL,
    credit_amount decimal(18,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS tmp_20250725_aux_opening;
CREATE TEMPORARY TABLE tmp_20250725_aux_opening (
    source_row int NOT NULL PRIMARY KEY,
    balance_id varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
    subject_code varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
    debit_amount decimal(18,2) NOT NULL,
    credit_amount decimal(18,2) NOT NULL,
    case_no varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
    receipt_no varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
    UNIQUE KEY uk_tmp_balance_id (balance_id),
    UNIQUE KEY uk_tmp_aux_combo (case_no,receipt_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;





START TRANSACTION;

-- 锁定目标账套，避免校验与写入之间被并发修改。
SELECT account_set_id INTO @locked_account_set_id
FROM fin_account_set
WHERE account_set_id=@account_set_id
FOR UPDATE;

DROP TEMPORARY TABLE IF EXISTS tmp_20250725_checks;
CREATE TEMPORARY TABLE tmp_20250725_checks (
    check_no int NOT NULL PRIMARY KEY,
    check_name varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
    actual_value varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
    expected_value varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
    ok_flag tinyint NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @check_account_set = (SELECT COUNT(*) FROM fin_account_set WHERE account_set_id=@account_set_id AND set_code='CASE_FUND_2025' AND biz_type='CASE_FUND' AND enabled_year=2025 AND enabled_period='2025-01' AND status=1 AND del_flag=0);
SET @check_period = (SELECT COUNT(*) FROM fin_fiscal_period WHERE account_set_id=@account_set_id AND period=@period AND status='OPEN' AND del_flag=0);
SET @check_subjects = (SELECT COUNT(*) FROM fin_subject WHERE account_set_id=@account_set_id AND del_flag=0 AND status=1 AND leaf_flag=1 AND voucher_entry_flag=1 AND ((subject_code='100201' AND direction='DEBIT') OR (subject_code IN ('200301','200302') AND direction='CREDIT')));
SET @check_aux_configs_required = (SELECT COUNT(*) FROM fin_subject_aux_config WHERE account_set_id=@account_set_id AND subject_code='200301' AND aux_type_code IN ('case_no','receipt_no') AND required_flag=1 AND del_flag=0);
SET @check_aux_configs_all = (SELECT COUNT(*) FROM fin_subject_aux_config WHERE account_set_id=@account_set_id AND subject_code='200301' AND del_flag=0);
SET @check_aux_types = (SELECT COUNT(*) FROM fin_aux_type WHERE account_set_id=@account_set_id AND aux_type_code IN ('case_no','receipt_no') AND value_source='MANUAL' AND status=1 AND del_flag=0);
SELECT COUNT(*),
       SUM(CASE WHEN case_no='' OR receipt_no='' THEN 1 ELSE 0 END),
       COALESCE(SUM(debit_amount),0),
       COALESCE(SUM(credit_amount),0),
       SUM(CASE WHEN debit_amount<0 OR credit_amount<0 THEN 1 ELSE 0 END),
       SUM(CASE WHEN source_row=63 AND debit_amount=0.00 AND credit_amount=-478.05 AND case_no='（2022）辽0111执1155号' AND receipt_no='0000564166' THEN 1 ELSE 0 END)
INTO @stage_count,@stage_blank_aux,@stage_debit_total,@stage_credit_total,@stage_negative_count,@stage_negative_expected
FROM tmp_20250725_aux_opening;
SELECT SUM(debit_amount),SUM(credit_amount)
INTO @subject_debit_total,@subject_credit_total
FROM tmp_20250725_opening_subject;
SET @opening_conflicts = (
    SELECT COUNT(*)
    FROM fin_opening_balance o
    JOIN tmp_20250725_opening_subject s ON s.subject_code=o.subject_code
    WHERE o.account_set_id=@account_set_id AND o.period=@period AND o.del_flag=0
      AND (o.debit_amount<>s.debit_amount OR o.credit_amount<>s.credit_amount)
      AND NOT (o.debit_amount=0.00 AND o.credit_amount=0.00)
);

 CONCAT(@subject_debit_total,' / ',@subject_credit_total),
 '34247184.19 / 34247184.19',
 @subject_debit_total=@subject_credit_total),
(12,'现有科目期初冲突',CAST(@opening_conflicts AS CHAR),'0',@opening_conflicts=0);

SET @existing_aux_active = (
    SELECT COUNT(*) FROM fin_aux_opening_balance
    WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0
);
SET @existing_aux_unmatched = (
    SELECT COUNT(*)
    FROM fin_aux_opening_balance a
    LEFT JOIN tmp_20250725_aux_opening s
      ON s.case_no=JSON_UNQUOTE(JSON_EXTRACT(a.aux_values_json,'$.case_no'))
     AND s.receipt_no=JSON_UNQUOTE(JSON_EXTRACT(a.aux_values_json,'$.receipt_no'))
     AND s.debit_amount=a.debit_amount
     AND s.credit_amount=a.credit_amount
    WHERE a.account_set_id=@account_set_id AND a.period=@period AND a.subject_code='200301' AND a.del_flag=0
      AND s.source_row IS NULL
);
SET @stage_aux_missing = (
    SELECT COUNT(*)
    FROM tmp_20250725_aux_opening s
    LEFT JOIN fin_aux_opening_balance a
      ON a.account_set_id=@account_set_id AND a.period=@period AND a.subject_code='200301' AND a.del_flag=0
     AND JSON_UNQUOTE(JSON_EXTRACT(a.aux_values_json,'$.case_no'))=s.case_no
     AND JSON_UNQUOTE(JSON_EXTRACT(a.aux_values_json,'$.receipt_no'))=s.receipt_no
     AND a.debit_amount=s.debit_amount
     AND a.credit_amount=s.credit_amount
    WHERE a.balance_id IS NULL
);
 CONCAT('active=',@existing_aux_active,',unmatched=',@existing_aux_unmatched,',missing=',@stage_aux_missing),
 '无活动数据，或与本批630行完全一致',
 @existing_aux_active=0 OR (@existing_aux_active=630 AND @existing_aux_unmatched=0 AND @stage_aux_missing=0)),
(14,'现有2025凭证（提示项）',
 CAST((SELECT COUNT(*) FROM fin_voucher WHERE account_set_id=@account_set_id AND fiscal_year=2025 AND del_flag=0) AS CHAR),
 '仅提示，不阻断本次已授权导入',
 1);

SELECT check_no,check_name,actual_value,expected_value,IF(ok_flag=1,'OK','FAIL') AS status
FROM tmp_20250725_checks
ORDER BY check_no;

DROP TEMPORARY TABLE IF EXISTS tmp_20250725_assert;
CREATE TEMPORARY TABLE tmp_20250725_assert (ok_flag tinyint NOT NULL) ENGINE=InnoDB;
SELECT IF(SUM(CASE WHEN ok_flag=0 THEN 1 ELSE 0 END)=0,1,NULL)
FROM tmp_20250725_checks;

SET @before_opening_json = (
    SELECT JSON_ARRAYAGG(JSON_OBJECT('subject_code',subject_code,'debit_amount',debit_amount,'credit_amount',credit_amount,'del_flag',del_flag))
    FROM fin_opening_balance
    WHERE account_set_id=@account_set_id AND period=@period AND subject_code IN ('100201','200301','200302')
);
SET @before_aux_json = JSON_OBJECT(
    'active_rows',@existing_aux_active,
    'debit_total',(SELECT COALESCE(SUM(debit_amount),0) FROM fin_aux_opening_balance WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0),
    'credit_total',(SELECT COALESCE(SUM(credit_amount),0) FROM fin_aux_opening_balance WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0)
);

-- 确保本批案号、收据号在手工辅助档案中可用；仅补充缺失的活动档案。
SELECT UUID(),@account_set_id,'case_no',s.case_no,s.case_no,1,@operator_id,CURRENT_TIMESTAMP,@operator_id,CURRENT_TIMESTAMP,0,0,CONCAT(@patch_tag,' 自动建档')
FROM (SELECT DISTINCT case_no FROM tmp_20250725_aux_opening) s
LEFT JOIN fin_aux_archive a
  ON a.account_set_id=@account_set_id AND a.aux_type_code='case_no' AND a.archive_code=s.case_no AND a.del_flag=0
WHERE a.archive_id IS NULL;
SET @inserted_case_archives = ROW_COUNT();

SELECT UUID(),@account_set_id,'receipt_no',s.receipt_no,s.receipt_no,1,@operator_id,CURRENT_TIMESTAMP,@operator_id,CURRENT_TIMESTAMP,0,0,CONCAT(@patch_tag,' 自动建档')
FROM (SELECT DISTINCT receipt_no FROM tmp_20250725_aux_opening) s
LEFT JOIN fin_aux_archive a
  ON a.account_set_id=@account_set_id AND a.aux_type_code='receipt_no' AND a.archive_code=s.receipt_no AND a.del_flag=0
WHERE a.archive_id IS NULL;
SET @inserted_receipt_archives = ROW_COUNT();

SELECT UUID(),@account_set_id,@period,s.subject_code,s.debit_amount,s.credit_amount,@operator_id,CURRENT_TIMESTAMP,@operator_id,CURRENT_TIMESTAMP,0,0,CONCAT('来源期初.xlsx；',@patch_tag)
FROM tmp_20250725_opening_subject s
WHERE 1=1
ON DUPLICATE KEY UPDATE
    debit_amount=VALUES(debit_amount),
    credit_amount=VALUES(credit_amount),
    updated_by=VALUES(updated_by),
    updated_time=VALUES(updated_time),
    del_flag=0,
    version=version+1,
    remark=VALUES(remark);

-- 保留历史记录：已有活动辅助期初先软删除，再恢复/写入本批确定ID的630行。
UPDATE fin_aux_opening_balance
SET del_flag=1,updated_by=@operator_id,updated_time=CURRENT_TIMESTAMP,version=version+1,remark=CONCAT(COALESCE(remark,''),'；由',@patch_tag,'替换')
WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0;

SELECT s.balance_id,@account_set_id,@period,'200301',
       JSON_OBJECT('case_no',s.case_no,'receipt_no',s.receipt_no),
       CONCAT('case_no:',s.case_no,' / receipt_no:',s.receipt_no),
       s.debit_amount,s.credit_amount,
       @operator_id,CURRENT_TIMESTAMP,@operator_id,CURRENT_TIMESTAMP,0,0,
       CONCAT('来源期初.xlsx第',s.source_row,'行；',@patch_tag)
FROM tmp_20250725_aux_opening s
WHERE 1=1
ON DUPLICATE KEY UPDATE
    account_set_id=VALUES(account_set_id),
    period=VALUES(period),
    subject_code=VALUES(subject_code),
    aux_values_json=VALUES(aux_values_json),
    aux_desc=VALUES(aux_desc),
    debit_amount=VALUES(debit_amount),
    credit_amount=VALUES(credit_amount),
    updated_by=VALUES(updated_by),
    updated_time=VALUES(updated_time),
    del_flag=0,
    version=version+1,
    remark=VALUES(remark);


-- 写入后事务内复核，失败即中止并回滚。
DROP TEMPORARY TABLE IF EXISTS tmp_20250725_post_checks;
CREATE TEMPORARY TABLE tmp_20250725_post_checks (ok_flag tinyint NOT NULL) ENGINE=InnoDB;
SELECT IF(
    (SELECT COUNT(*) FROM fin_opening_balance o JOIN tmp_20250725_opening_subject s ON s.subject_code=o.subject_code AND s.debit_amount=o.debit_amount AND s.credit_amount=o.credit_amount WHERE o.account_set_id=@account_set_id AND o.period=@period AND o.del_flag=0)=3
    AND (SELECT COUNT(*) FROM fin_aux_opening_balance WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0)=630
    AND (SELECT COALESCE(SUM(debit_amount),0) FROM fin_aux_opening_balance WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0)=0.00
    AND (SELECT COALESCE(SUM(credit_amount),0) FROM fin_aux_opening_balance WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0)=33415388.11
    AND (SELECT COUNT(*) FROM fin_aux_opening_balance WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0 AND (JSON_UNQUOTE(JSON_EXTRACT(aux_values_json,'$.case_no'))='' OR JSON_UNQUOTE(JSON_EXTRACT(aux_values_json,'$.receipt_no'))=''))=0
,1,NULL);

COMMIT;

-- 最终对账输出。
SELECT subject_code,debit_amount,credit_amount,credit_amount-debit_amount AS net_credit_amount,del_flag,updated_time,remark
FROM fin_opening_balance
WHERE account_set_id=@account_set_id AND period=@period AND subject_code IN ('100201','200301','200302')
ORDER BY subject_code;

SELECT COUNT(*) AS aux_rows,
       SUM(debit_amount) AS aux_debit_total,
       SUM(credit_amount) AS aux_credit_total,
       SUM(credit_amount-debit_amount) AS aux_net_credit_total,
       SUM(CASE WHEN debit_amount<0 OR credit_amount<0 THEN 1 ELSE 0 END) AS negative_exception_rows,
       COUNT(DISTINCT CONCAT(JSON_UNQUOTE(JSON_EXTRACT(aux_values_json,'$.case_no')),'\0',JSON_UNQUOTE(JSON_EXTRACT(aux_values_json,'$.receipt_no')))) AS distinct_aux_combinations
FROM fin_aux_opening_balance
WHERE account_set_id=@account_set_id AND period=@period AND subject_code='200301' AND del_flag=0;

SELECT SUM(debit_amount) AS opening_debit_total,
       SUM(credit_amount) AS opening_credit_total,
       SUM(debit_amount)-SUM(credit_amount) AS trial_balance_difference
FROM fin_opening_balance
WHERE account_set_id=@account_set_id AND period=@period AND subject_code IN ('100201','200301','200302') AND del_flag=0;

SELECT @inserted_case_archives AS inserted_case_archives,
       @inserted_receipt_archives AS inserted_receipt_archives,
       @source_sha256 AS source_sha256;

DROP TEMPORARY TABLE IF EXISTS tmp_20250725_post_checks;
DROP TEMPORARY TABLE IF EXISTS tmp_20250725_assert;
DROP TEMPORARY TABLE IF EXISTS tmp_20250725_checks;
DROP TEMPORARY TABLE IF EXISTS tmp_20250725_aux_opening;
DROP TEMPORARY TABLE IF EXISTS tmp_20250725_opening_subject;

